-- The Black Morass: the Infinite Dragonflight attackers and the rift guardians have no AI, so they only melee
-- and never speak. The instance script summons them, so they have no spawn rows and never got SmartAI.
-- Idempotent: every INSERT is preceded by a DELETE of its keys.

UPDATE `creature_template` SET `AIName`='SmartAI' WHERE `entry` IN (17835, 17839, 17892, 18994, 18995, 21104, 21818) AND `ScriptName`='';

DELETE FROM `smart_scripts` WHERE `source_type`=0 AND `entryorguid` IN (17835, 17839, 17892, 18994, 18995, 21104, 21818);

DELETE FROM `creature_text` WHERE `entry` IN (17835, 17839, 17892, 21104);
